// @ts-nocheck
export const code = async (inputs) => {
  const C = {
    "app_url": "{{trigger['body']['app_url']}}",
    "inbound_token": "{{trigger['body']['inbound_token']}}",
    "company_name": "{{trigger['body']['company_name']}}",
    "flow": "STUDENT_MANAGE",
    "brand_tone": "formal, precise, courteous",
    "brand_signature": "",
    "followup_days": [
      2,
      5,
      10
    ],
    "quote_validity_days": 30,
    "same_day_quote_hours": 8,
    "default_owner": "",
    "own_domain": "",
    "quote_series": "SMT/Q",
    "catalogue": [],
    "options": [],
    "owners": [],
    "whatsapp_account_id": "SET_IN_STUDIO_WHATSAPP_ACCOUNT_ID",
    "whatsapp_templates": {
      "enrol": "SET_IN_STUDIO_TEMPLATE_ID_ENROL"
    },
    "whatsapp_template_names": {
      "enrol": "eduflow_welcome"
    }
  };
  // v5.1: the app sends app_url, inbound_token and company_name with every call (the step's inputs, from the trigger body)
  C.app_url = String(inputs.app_url || '').replace(/\/+$/, ''); C.inbound_token = String(inputs.inbound_token || ''); C.company_name = String(inputs.company_name || '');
  if (!C.brand_signature) C.brand_signature = 'For ' + C.company_name;
  C.today = new Date().toISOString(); C.year = new Date().getFullYear();
  C.catalogue_text = C.catalogue.map(c => c.code + ' = ' + c.name + (c.product_line ? ' (' + c.product_line + ')' : '')).join('; ');
  C.options_for_model = (C.options || []).filter(o => o.model === ((inputs.body || {}).Model_Code || '')).map(o => o.code + ' = ' + o.description).join('; ');
  return C;
};

// @ts-nocheck
export const code = async (inputs) => { const p = { ...(inputs.b || {}) }; const JEVP = {}; for (const k of Object.keys(inputs)) if (k.indexOf('jev_') === 0 && k.slice(-11) !== '_confidence') { const f = k.slice(4), v = inputs[k], conf = Number(inputs[k + '_confidence']); const pol = JEVP[f] || [0.5, null]; if (v !== undefined && v !== '' && (isNaN(conf) || conf >= pol[0])) p[f] = v; else if (pol[1] !== null && pol[1] !== undefined) p[f] = pol[1]; } /* a Jev answer lands only when confident; else the fallback */ const now = new Date().toISOString(); const allowed = ["Student_ID", "Enrolled_At", "Name", "Student_Phone", "Parent_Name", "Parent_Phone", "Course", "Batch", "Address", "Status", "Attendance_Pct", "Last_Score", "Avg_Score", "Class_Rank", "Strong_Subjects", "Weak_Subjects", "Performance_Trend", "Fee_Status", "Fee_Amount_INR", "Fee_Due_Date", "Mentor", "Counsellor", "Issue_Type", "Main_Issue", "Last_Counselled_At", "Last_Report_At", "Last_Parent_Call_At", "Parent_Sentiment", "Parent_Concern"]; const map = {"Phone": "Student_Phone"}; const fill = {"Status": "Active", "Fee_Status": "Due", "Enrolled_At": "now"};
  const src = { ...p }; for (const [k, c] of Object.entries(map)) if (p[k] !== undefined) src[c] = p[k];
  const row = {}; for (const k of allowed) row[k] = src[k] === undefined ? '' : src[k]; for (const [k, v] of Object.entries(fill)) row[k] = v === 'now' ? now : v;
  if (!row['Enrolled_At']) row['Enrolled_At'] = now;
  return { row };
};

// @ts-nocheck
// lib: the app's src/lib/renderMessage.js, copied verbatim so the flow and the app word a message the same way
// src/lib/renderMessage.js — a client message from a fixed template (os.yaml `sends.message`), rule zero: the words
// are the firm's, the values are the record's, no model is involved. ONE source: the app imports it to show what a
// simulated send would have said, and build_flows.py embeds this same file in the flow's CODE node, so the wired flow
// and the simulation can never word a message differently. Plain JS, no imports — it must run inside Studio as is.
//   send = { to: <payload key>, lang: <payload key>, message: { en, hi, mr, … }, words: { hi: { Adjourned: '…' } }, template: { name, variables: { '1': '{{Col}}' } } }
//   {{Key}} → the payload value · {{constants.x}} → the flow constant · [[ … ]] → dropped when any value inside is empty
//   dates (YYYY-MM-DD or ISO) → "Thu, 2 Oct 2026" / "Thu, 2 Oct 2026, 4:30 pm" in IST · phone → digits with 91 prefix
function renderMessage(send, vars, constants) {
  const LANG = { english: 'en', en: 'en', hindi: 'hi', hi: 'hi', marathi: 'mr', mr: 'mr', gujarati: 'gu', gu: 'gu', tamil: 'ta', ta: 'ta', telugu: 'te', te: 'te', kannada: 'kn', kn: 'kn', bengali: 'bn', bn: 'bn', malayalam: 'ml', ml: 'ml', punjabi: 'pa', pa: 'pa' };
  const msg = (send && send.message) || {};
  const asked = LANG[String((vars || {})[send.lang] || '').trim().toLowerCase()] || 'en';
  const lang = msg[asked] ? asked : (msg.en ? 'en' : Object.keys(msg)[0]);
  const words = ((send.words || {})[lang]) || {};
  const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'], MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  const date = (v) => {
    const only = /^\d{4}-\d{2}-\d{2}$/.test(v);
    const t = only ? Date.UTC(+v.slice(0, 4), +v.slice(5, 7) - 1, +v.slice(8, 10)) : Date.parse(v) + 330 * 60000;   // IST without Intl
    if (isNaN(t)) return v; const d = new Date(t);
    let s = `${DAYS[d.getUTCDay()]}, ${d.getUTCDate()} ${MONTHS[d.getUTCMonth()]} ${d.getUTCFullYear()}`;
    if (!only) { const h = d.getUTCHours(), m = d.getUTCMinutes(); s += `, ${((h + 11) % 12) + 1}:${String(m).padStart(2, '0')} ${h < 12 ? 'am' : 'pm'}`; }
    return s;
  };
  const val = (k) => {
    let v = k.indexOf('constants.') === 0 ? (constants || {})[k.slice(10)] : (vars || {})[k];
    if (v === undefined || v === null) return '';
    v = String(v).trim();
    if (/^\d{4}-\d{2}-\d{2}([T ][\d:.]+(Z|[+-]\d{2}:?\d{2})?)?$/.test(v)) v = date(v);
    return words[v] !== undefined ? words[v] : v;
  };
  const fill = (s) => s.replace(/\{\{\s*([\w.]+)\s*\}\}/g, (_, k) => val(k));
  let text = String(msg[lang] || '')
    .replace(/\[\[([\s\S]*?)\]\]/g, (_, part) => (part.match(/\{\{\s*([\w.]+)\s*\}\}/g) || []).every((p) => val(p.replace(/[{}\s]/g, '')) !== '') ? part : '');
  text = fill(text).replace(/[ \t]{2,}/g, ' ').replace(/ +([.,।])/g, '$1').trim();
  const digits = String((vars || {})[send.to] || '').replace(/\D/g, '');
  const to = digits.length === 10 ? '91' + digits : digits;
  // v4.4 — an approved WhatsApp template (os.yaml `sends.template`): the words live on whatsapp.pucho.ai, the flow fills only the
  // variables, each a {{Column}} template rendered the same way as a message. `to_e164` is the `+91…` form pucho-whatsapp takes.
  const tpl = send && send.template; const variables = {};
  if (tpl && tpl.variables) for (const k of Object.keys(tpl.variables)) variables[k] = fill(String(tpl.variables[k])).trim();
  return { to, to_e164: to ? '+' + to : '', lang, text, template: tpl ? (tpl.name || '') : '', variables };
}

// end lib
const SEND = {"tool": "whatsapp", "to": "Parent_Phone", "template": {"name": "eduflow_welcome", "variables": {"1": "{{Parent_Name}}", "2": "{{Name}}", "3": "{{Course}}", "4": "{{Batch}}"}}};
export const code = async (inputs) => renderMessage(SEND, { ...(inputs.b || {}), ...(inputs.row || {}) }, inputs.C || {});
